INSERT INTO attendance_report_oa_fact ( attendance_report_oa_fact_id, attendance_report_projection_id, company_id, oa_attendance_document_id, employee_id, employee_version_id, employment_period_id, organization_id, organization_version_id, document_type, leave_type_code, temporal_shape, point_instant, interval_start, interval_end, recognized_minutes, source_status, source_version, created_at ) SELECT UUID(), #{targetProjectionId}, company_id, oa_attendance_document_id, employee_id, employee_version_id, employment_period_id, organization_id, organization_version_id, document_type, leave_type_code, temporal_shape, point_instant, interval_start, interval_end, recognized_minutes, source_status, source_version, #{createdAt} FROM attendance_report_oa_fact WHERE attendance_report_projection_id = #{sourceProjectionId} AND NOT (
employee_id IN
#{id}
employee_id = #{employeeId}
AND ( ( interval_start IS NOT NULL AND interval_start < #{windowEndExclusive} AND interval_end > #{windowStart} ) OR ( point_instant IS NOT NULL AND point_instant >= #{windowStart} AND point_instant < #{windowEndExclusive} ) ) )

